content.css:
.efr-root {
  --efr-font-family: "Segoe UI", wf_segoe-ui_normal, helvetica, arial, sans-serif;
  --efr-axis-title-font: 12px;
  --efr-axis-label-font: 11px;
  --efr-legend-font: 11px;
  --efr-data-label-font: 9px;
  --efr-insight-font: 11px;
  --efr-insight-header-font: 12px;
  --efr-insight-accent: #E8612A;
  --efr-soft: #F8F9FB;
  --efr-rule: #E5E7EB;
  --efr-text: #242424;
  --efr-muted: #6C757D;
  width: 100%;
  height: 100%;
  overflow: hidden;
  font-family: var(--efr-font-family);
  color: var(--efr-text);
  padding-bottom: 24px;
  box-sizing: border-box;
  position: relative;
}
.efr-root svg {
  shape-rendering: geometricPrecision;
}
.efr {
  width: 100%;
  height: 100%;
  display: flex;
  flex-direction: column;
  background: linear-gradient(180deg, #FFFFFF 0%, var(--efr-soft) 100%);
}
/* =================================================================== */
/* Header                                                              */
/* =================================================================== */
.efr-header {
  position: relative;
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 6px 10px 4px 10px;
  border-bottom: 1px solid var(--efr-rule);
  background: transparent;
  min-height: 24px;
  box-sizing: border-box;
}
.efr-header__titles {
  flex: 1 1 auto;
  min-width: 0;
  display: flex;
  flex-direction: column;
  line-height: 1.15;
}
.efr-header__title {
  font-weight: 700;
  color: var(--efr-text);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.efr-header__subtitle {
  color: var(--efr-muted);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.efr-header__info {
  flex: 0 0 auto;
  width: 20px;
  height: 20px;
  border-radius: 50%;
  border: 1px solid var(--efr-rule);
  background: #fff;
  color: var(--efr-muted);
  display: flex;
  align-items: center;
  justify-content: center;
  font-style: italic;
  font-weight: 700;
  font-size: 11px;
  cursor: pointer;
  user-select: none;
  transition: background 0.15s, color 0.15s, border-color 0.15s;
}
.efr-header__info:hover,
.efr-header__info:focus {
  background: var(--efr-insight-accent);
  color: #fff;
  border-color: var(--efr-insight-accent);
  outline: none;
}
.efr-header__budget {
  --efr-budget-accent: #E8612A;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 3px 10px 3px 10px;
  margin-right: 6px;
  border: 1px solid var(--efr-rule);
  border-radius: 999px;
  background: #fff;
  font-size: 11px;
  color: var(--efr-text);
  flex: 0 1 auto;
  min-width: 0;
}
.efr-header__budget-label {
  font-weight: 700;
  color: var(--efr-budget-accent);
  white-space: nowrap;
}
.efr-header__budget-range {
  -webkit-appearance: none;
  appearance: none;
  height: 4px;
  width: 140px;
  background: linear-gradient(to right, var(--efr-budget-accent) 0%, var(--efr-budget-accent) var(--efr-budget-pct, 100%), #E5E7EB var(--efr-budget-pct, 100%), #E5E7EB 100%);
  border-radius: 2px;
  outline: none;
  cursor: pointer;
  flex: 0 1 140px;
  min-width: 60px;
}
.efr-header__budget-range::-webkit-slider-thumb {
  -webkit-appearance: none;
  appearance: none;
  width: 14px;
  height: 14px;
  border-radius: 50%;
  background: #fff;
  border: 2px solid var(--efr-budget-accent);
  cursor: grab;
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.18);
}
.efr-header__budget-range::-moz-range-thumb {
  width: 14px;
  height: 14px;
  border-radius: 50%;
  background: #fff;
  border: 2px solid var(--efr-budget-accent);
  cursor: grab;
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.18);
}
.efr-header__budget-value {
  font-weight: 700;
  color: var(--efr-text);
  font-variant-numeric: tabular-nums;
  min-width: 44px;
  text-align: right;
  white-space: nowrap;
}
.efr-header__info-pop {
  position: absolute;
  top: calc(100% + 4px);
  right: 8px;
  z-index: 30;
  display: none;
  width: 320px;
  max-width: calc(100% - 16px);
  background: #fff;
  border: 1px solid var(--efr-rule);
  border-radius: 6px;
  box-shadow: 0 6px 18px rgba(0, 0, 0, 0.12);
  padding: 10px 12px;
  font-size: var(--efr-insight-font);
  color: var(--efr-text);
  line-height: 1.4;
}
.efr-header__info-pop-title {
  font-weight: 700;
  font-size: var(--efr-insight-header-font);
  margin-bottom: 4px;
  color: var(--efr-text);
}
.efr-header__info-pop-desc {
  margin: 0 0 6px 0;
  color: var(--efr-text);
}
.efr-header__info-pop-list {
  margin: 0;
  padding-left: 16px;
  color: var(--efr-muted);
}
.efr-header__info-pop-list li {
  margin-bottom: 2px;
}
/* =================================================================== */
/* Body                                                                */
/* =================================================================== */
.efr-body {
  flex: 1 1 auto;
  display: flex;
  flex-direction: row;
  min-height: 0;
  position: relative;
}
.efr-chart-wrap {
  flex: 1 1 auto;
  min-width: 0;
  position: relative;
}
.efr-universe-canvas {
  position: absolute;
  top: 0;
  left: 0;
  pointer-events: none;
  z-index: 1;
}
.efr-svg {
  position: relative;
  z-index: 2;
  width: 100%;
  height: 100%;
  display: block;
}
.efr-panel__warn {
  font-size: calc(var(--efr-insight-font) - 1px);
  color: #92400E;
  background: #FEF3C7;
  border: 1px solid #FDE68A;
  border-radius: 3px;
  padding: 5px 8px;
  margin-bottom: 8px;
  line-height: 1.3;
}
/* =================================================================== */
/* Insight strip + panel                                               */
/* =================================================================== */
.efr-insight-strip {
  flex: 0 0 24px;
  width: 24px;
  background: var(--efr-soft);
  border-left: 1px solid var(--efr-rule);
  border-right: 1px solid var(--efr-rule);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  user-select: none;
  color: var(--efr-muted);
  transition: background 0.15s;
}
.efr-insight-strip:hover {
  background: #F0F2F6;
}
.efr-insight-strip__arrow {
  font-size: 11px;
  color: var(--efr-insight-accent);
  margin-bottom: 8px;
}
.efr-insight-strip__label {
  writing-mode: vertical-rl;
  transform: rotate(180deg);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 2px;
  color: var(--efr-muted);
}
.efr-insight-panel {
  flex: 0 0 250px;
  max-width: 320px;
  background: linear-gradient(180deg, #FFFFFF 0%, var(--efr-soft) 100%);
  border-left: 1px solid var(--efr-rule);
  padding: 8px 10px 10px 10px;
  overflow-y: auto;
  box-sizing: border-box;
  font-size: var(--efr-insight-font);
}
.efr--insight-collapsed .efr-insight-panel {
  display: none;
}
.efr--insight-hidden .efr-insight-strip,
.efr--insight-hidden .efr-insight-panel {
  display: none;
}
/* Narrow: panel overlays chart */
.efr-root.efr-narrow .efr-insight-panel {
  position: absolute;
  right: 0;
  top: 0;
  height: 100%;
  z-index: 10;
  box-shadow: -4px 0 14px rgba(0, 0, 0, 0.08);
}
/* =================================================================== */
/* Panel content                                                       */
/* =================================================================== */
.efr-panel__header {
  border-bottom: 2px solid var(--efr-insight-accent);
  padding-bottom: 4px;
  margin-bottom: 8px;
}
.efr-panel__title {
  font-weight: 700;
  font-size: var(--efr-insight-header-font);
  color: var(--efr-text);
}
.efr-panel__count {
  color: var(--efr-muted);
  font-size: calc(var(--efr-insight-font) - 1px);
  margin-top: 1px;
}
.efr-panel__kpis {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 6px;
  margin-bottom: 10px;
}
.efr-kpi {
  --efr-kpi-accent: var(--efr-insight-accent);
  background: #FFFFFF;
  border: 1px solid var(--efr-rule);
  border-left: 3px solid var(--efr-kpi-accent);
  border-radius: 3px;
  padding: 5px 7px;
  line-height: 1.2;
}
.efr-kpi__val {
  font-weight: 700;
  color: var(--efr-text);
  font-size: var(--efr-insight-font);
}
.efr-kpi__lbl {
  color: var(--efr-muted);
  font-size: calc(var(--efr-insight-font) - 2px);
  margin-top: 1px;
}
.efr-panel__smart {
  margin: 0 0 10px 0;
  padding-left: 16px;
  color: var(--efr-text);
  font-size: var(--efr-insight-font);
}
.efr-panel__smart li {
  margin-bottom: 4px;
  line-height: 1.35;
}
.efr-panel__smart li strong {
  color: var(--efr-text);
  font-weight: 700;
}
.efr-panel__smart li em {
  color: var(--efr-muted);
  font-style: italic;
}
.efr-panel__mini {
  margin: 4px 0 12px 0;
  padding: 8px;
  background: #FFFFFF;
  border: 1px solid var(--efr-rule);
  border-radius: 4px;
}
.efr-panel__mini-title {
  font-weight: 700;
  font-size: calc(var(--efr-insight-font) - 1px);
  text-transform: uppercase;
  letter-spacing: 0.5px;
  color: var(--efr-muted);
  margin-bottom: 2px;
}
.efr-panel__mini-sub {
  font-size: calc(var(--efr-insight-font) - 2px);
  color: var(--efr-muted);
  margin-bottom: 6px;
  line-height: 1.3;
}
.efr-panel__mini-row {
  display: grid;
  grid-template-columns: max-content minmax(30px, 1fr) max-content;
  align-items: center;
  gap: 6px;
  padding: 3px 2px;
  cursor: pointer;
  border-radius: 3px;
  min-height: 18px;
}
.efr-panel__mini-row:hover,
.efr-panel__mini-row.is-hovered {
  background: rgba(232, 97, 42, 0.08);
}
.efr-panel__mini-row.is-selected {
  background: rgba(31, 42, 68, 0.1);
  font-weight: 600;
}
.efr-panel__mini-row .efr-panel__mini-lbl {
  font-size: calc(var(--efr-insight-font) - 1px);
  color: var(--efr-text);
  white-space: nowrap;
}
.efr-panel__mini-row .efr-panel__mini-track {
  position: relative;
  height: 10px;
  width: 100%;
  background: #EEF1F5;
  border-radius: 2px;
  overflow: hidden;
  min-width: 30px;
}
.efr-panel__mini-row .efr-panel__mini-fill {
  position: absolute;
  top: 0;
  left: 0;
  bottom: 0;
  height: 100%;
  background: var(--efr-insight-accent);
  border-radius: 2px;
  transition: width 0.2s ease;
}
.efr-panel__mini-row .efr-panel__mini-val {
  font-size: calc(var(--efr-insight-font) - 1px);
  color: var(--efr-muted);
  font-variant-numeric: tabular-nums;
  text-align: right;
  white-space: nowrap;
}
.efr-panel__mini--pinned {
  border-left: 3px solid var(--efr-insight-accent);
  background: #FFFDF6;
}
.efr-panel__mini--rebalance {
  border-left: 3px solid #10B981;
  background: #F7FBF8;
}
.efr-cut-handle:hover + .efr-cut-line,
.efr-cut-handle:active + .efr-cut-line {
  stroke-width: 2.4px;
}
.efr-cut-label {
  font-family: var(--efr-font-family);
  pointer-events: none;
  user-select: none;
}
/* High-contrast tweaks — swap soft brand palette for system colors so the
 * chart stays legible against a black/white system background.            */
.efr-root.efr--hc {
  background: Canvas;
  color: CanvasText;
}
.efr-root.efr--hc .efr-frontier-line {
  stroke: Highlight;
}
.efr-root.efr--hc .efr-cal-line {
  stroke: GrayText;
}
.efr-root.efr--hc .efr-cut-line {
  stroke: HighlightText;
}
.efr-root.efr--hc .efr-axis .tick text {
  fill: CanvasText;
}
.efr-root.efr--hc .efr-axis-label {
  fill: CanvasText;
}
.efr-root.efr--hc .efr-grid-line {
  stroke: GrayText;
}
.efr-panel__list {
  margin-bottom: 10px;
}
.efr-panel__list-title {
  font-weight: 700;
  font-size: calc(var(--efr-insight-font) - 1px);
  text-transform: uppercase;
  letter-spacing: 0.5px;
  color: var(--efr-muted);
  margin-bottom: 3px;
}
.efr-panel__row {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 3px 4px;
  border-radius: 3px;
  cursor: pointer;
  transition: background 0.12s;
}
.efr-panel__row:hover,
.efr-panel__row.is-hovered {
  background: rgba(232, 97, 42, 0.08);
}
.efr-panel__row.is-selected {
  background: rgba(31, 42, 68, 0.1);
  font-weight: 600;
}
.efr-panel__row .efr-panel__dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  flex: 0 0 8px;
}
.efr-panel__row .efr-panel__name {
  flex: 1 1 auto;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: var(--efr-text);
}
.efr-panel__row .efr-panel__val {
  color: var(--efr-muted);
  font-variant-numeric: tabular-nums;
}
/* =================================================================== */
/* Landing + empty                                                     */
/* =================================================================== */
.efr-landing,
.efr-empty {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px 24px;
  box-sizing: border-box;
  text-align: center;
}
.efr-landing {
  color: #888;
  font-size: 13px;
}
.efr-empty {
  color: #94a3b8;
  font-size: 12px;
  letter-spacing: 0.2px;
}
/* =================================================================== */
/* Chart                                                               */
/* =================================================================== */
.efr-axis .tick line {
  stroke: #d0d0d0;
  stroke-width: 0.5;
}
.efr-axis .tick text {
  fill: #666;
  font-size: var(--efr-axis-label-font);
}
.efr-axis .domain {
  stroke: #aaa;
  stroke-width: 1;
}
.efr-axis-label {
  fill: #444;
  font-size: var(--efr-axis-title-font);
  font-weight: 600;
}
.efr-frontier-line {
  fill: none;
  stroke-linecap: round;
  stroke-linejoin: round;
}
.efr-cal-line {
  fill: none;
}
.efr-scatter-point {
  stroke: #fff;
  stroke-width: 1.2;
  cursor: pointer;
  transition: opacity 0.15s ease, stroke-width 0.12s ease, r 0.12s ease;
}
.efr-scatter-point:hover {
  stroke-width: 2;
  filter: brightness(1.15);
}
.efr-scatter-point.dimmed {
  opacity: 0.22;
}
.efr-scatter-point.selected {
  stroke: #1F2A44;
  stroke-width: 2;
}
.efr-scatter-point.hovered {
  stroke: var(--efr-insight-accent);
  stroke-width: 2;
}
.efr-data-label {
  font-size: var(--efr-data-label-font);
  fill: #555;
}
.efr-optimal-label {
  font-size: var(--efr-data-label-font);
}
.efr-legend {
  font-size: var(--efr-legend-font);
  fill: #555;
}
.efr-legend-swatch {
  stroke: #fff;
  stroke-width: 0.5;
}
.efr-grid-line {
  stroke: #e8e8e8;
  stroke-width: 0.5;
  stroke-dasharray: 3 3;
}
/* =================================================================== */
/* Responsive                                                          */
/* =================================================================== */
.efr-root.efr-medium .efr-insight-panel {
  flex: 0 0 220px;
}
.efr-root.efr-narrow .efr-insight-panel {
  flex: 0 0 240px;
}
.efr-root.efr-narrow .efr-insight-strip {
  border-left: none;
}
/* =================================================================== */
/* License badge + watermark                                           */
/* =================================================================== */
.bfusion-license-badge-wrap {
  position: absolute;
  bottom: 4px;
  left: 8px;
  z-index: 20;
  pointer-events: none;
}
.bfusion-license-badge {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 3px 10px;
  border-radius: 4px;
  font-size: 9px;
  font-family: "Segoe UI", wf_segoe-ui_normal, helvetica, arial, sans-serif;
  line-height: 1.3;
  pointer-events: auto;
  max-width: 380px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.bfusion-license-badge--valid {
  background: rgba(5, 150, 105, 0.08);
  border: 1px solid rgba(5, 150, 105, 0.25);
  color: #059669;
}
.bfusion-license-badge--invalid {
  background: rgba(220, 38, 38, 0.06);
  border: 1px solid rgba(220, 38, 38, 0.2);
  color: #DC2626;
}
.bfusion-license-badge__icon {
  font-size: 11px;
  flex-shrink: 0;
}
.bfusion-license-badge__text {
  overflow: hidden;
  text-overflow: ellipsis;
}
.bfusion-license-badge__text strong {
  font-weight: 600;
}
.bfusion-watermark {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  z-index: 15;
  pointer-events: none;
  display: flex;
  align-items: center;
  justify-content: center;
  background: repeating-linear-gradient(-45deg, transparent, transparent 120px, rgba(220, 38, 38, 0.03) 120px, rgba(220, 38, 38, 0.03) 122px);
}
.bfusion-watermark__content {
  text-align: center;
  opacity: 0.18;
  user-select: none;
  transform: rotate(-18deg);
}
.bfusion-watermark__title {
  font-size: 56px;
  font-weight: 900;
  color: #DC2626;
  letter-spacing: 12px;
  line-height: 1;
  font-family: "Segoe UI", sans-serif;
}
.bfusion-watermark__subtitle {
  font-size: 16px;
  font-weight: 600;
  color: #DC2626;
  margin-top: 6px;
  letter-spacing: 3px;
  text-transform: uppercase;
  font-family: "Segoe UI", sans-serif;
}
.bfusion-watermark__link {
  font-size: 11px;
  color: #9CA3AF;
  margin-top: 12px;
  font-family: "Segoe UI", sans-serif;
}
